def min_diameter(points):
    xs, ys = [], []
    for x, y in points:
        if x > 0:
            xs.append(x)
        elif x < 0:
            ys.append(x)
        if y > 0:
            xs.append(y)
        elif y < 0:
            ys.append(y)
    xs.sort()
    ys.sort()

    n = len(xs)
    if n % 2 == 0:
        left = n // 2 - 1
        right = right = n // 2
    else:
        left = n // 2
        right = n // 2

    min_dist = float('inf')
    for i in range(left + 1, right):
        min_dist = min(min_dist, xs[i] - xs[right])

    return min(min_dist, ys[left] - ys[right]) ** 2

