    restriction_weights = [[0] * (h + 1) for _ in range(n + 1)]

    for l, r, x, c in restrictions:
        for i in range(l - 1, r):
            for j in range(x, h + 1):
                dp[i][j] = max(dp[i][j], dp[i-1][j - x] - c)
                if j - x > 0:
                    restriction_weights[i][j - x] += 1

    max_profit = sum(j ** 2 for j in range(1, h + 1)) - sum(
        max(dp[i][j] - restriction * restriction_weights[i][j] for i in range(n)) for j in range(h + 1)
    )

