import math

def smallest_divisor(n, k):
    """Returns the smallest divisor of n that is <= k."""
    if n % 2 == 0:
        return 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return i
    return n  # n is prime or 1 if not found

def count_numbers(n, k):
    """Counts the numbers in the range [a, b] that are divisible by k and don't have a smaller divisor."""
    a, b, k = n
    it = 0
    first = []
    for i in range(a, b + 1):
        if smallest_divisor(i, k) == k:
            if i % k == 0:
                it += 1
                # Check if i/k is less than sqrt(b)
                if i // k < math.sqrt(b):
                    first.append(i)
    return it + len(first)

