    counts[0] = 1
    counts[1] = 1

    for i in range(2, n + 1):
        for j in range(min(i, m), 0, -1):
            counts[j] = (counts[j] - counts[j - i] + MOD) % MOD

    total_count = 0
    for j in range(m // 2 + 1):
        total_count = (total_count + 1LL * comb(m, j) * counts[j]) % MOD

    total_count = total_count - n
    for j in range(1, n + 1):
