from heapq import heappush, heappop
from collections import defaultdict

# Build the tree from input
def build_tree(n):
    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        tree[a - 1].append((b - 1, a))
        tree[b - 1].append((a, b))
    return tree

# Calculate the distance from any vertex to all other vertices
def dijkstra_tree(tree, n, start):
    distance = [float('inf')] * n
    distance[start] = 0
    visited = [False] * n
    priority_queue = [(0, start)]
    while priority_queue:
        current_dist, u = heappop(priority_queue)
        visited[u] = True
        if visited[u]:
            continue
        for v, w in tree[u]:
            weight = 1 if v == start else w
            if current_dist + weight < distance[v]:
                distance[v] = current_dist + weight
                heappush(priority_queue, (current_dist + weight, v))
    return distance

# Solve the problem
def solve(t, tree, start1, end1, start2, end2):
    n = len(tree)
    distance1 = dijkstra_tree(tree, n, start1)
    distance2 = dijkstra_tree(tree, n, start2)

    path1 = []
    node2 = -1
    for i in range(n - 1, -1, -1):
        w = distance1[i]
        if w < distance2[node2]:
            path1.append([i, n - 1 - w])
            node2 = n - 1 - w

    path2 = []
    node2 = -1
    for i in range(n - 1, -1, -1):
        w = distance2[i]
        if w < distance1[node2]:
            path2.append([i, n - 1 - w])
            node2 = n - 1 - w

    common = None
    i = j = 0
    while i < len(path1) and j < len(path2):
        dist1 = path1[i][0]
        dist2 = path2[j][0]
        if dist1 == dist2:
            if i == j:
                common = [n - 1 - path1[i][1] + 1]
            else:
                common = [path1[i][1] + path2[j][1] + 2]
            i += 1
            j += 1
        elif distance1[dist1] < distance2[dist2]:
            common = path1[i][1] + path2[j][1] + 2
            i += 1
        else:
            common = path1[i][1] + path2[j][1] + 2
            j += 1

    if not common:
        if j == len(path2):
            return "0"
        else:
            return "-1"

    return " ".join(map(str, common))

# Main
if __name__ == "__main__":
    n = int(input())
    tree = build_tree(n)
    t = int(input())
    for _ in range(t):
        start1, end1, start2, end2 = map(int, input().split())
        print(solve(t, tree, start1, end1, start2, end2))
