            break

def find_set(node, parent):
    if parent[node] != node:
        parent[node] = find_set(parent[node], parent)
    return parent[node]

def union_sets(node1, node2, parent, rank):
    root1, root2 = find_set(node1, parent), find_set(node2, parent)
    if root1 == root2:
        return
    if rank[root1] < rank[root2]:
        parent[root1] = root2
    elif rank[root1] > rank[root2]:
        parent[root2] = root1
    else:
        parent[root2] = root1
        rank[root1] += 1

def is_in_same_set(node1, node2, parent, rank):
    root1, root2 = find_set(node1, parent), find_set(node2, parent)
    return root1 == root2

def construct_tree(edges, n):
    parent = [i for i in range(n + 1)]
    rank = [0] * (n + 1)
    for u, v, w in edges:
        if not is_in_same_set(u, v, parent, rank):
            union_sets(u, v, parent, rank)
    result = [-1] * (n + 1)
    for i in range(1, n + 1):
        result[i] = w
    for node1, node2, w in edges:
        count = sum(i[1] == result[i[1]] for i in edges if i[0] == node1 or i[0] == node2)
        if count == 1 or is_in_same_set(node1, node2, parent, rank):
            result[node1] = result[node2] = w
    return result[1:]

