    """Calculate the modular inverse of a mod mod using the Extended Euclidean Algorithm."""
    m_inv = -1
    a, b = a, mod
    t1, t2 = 0, 1
    while b > 0:
        q = a // b
        a, b = b, a % b
        t1, t2 = t2 - q * t1, t1
    if a != 1:
        return -1
    else:
        return t2 % mod

