    for i in range(size):
        if value[i] >= best + f[i]: 
            best += f[i]
        if value[i] > best + f[size-1]: 
            return i
    return size

def subarray_size(size, fibs_till_n, a):
    n = size - 1
    if not a: 
        return 0
    ans = 0
    idx = n
    prev = fibs_till_n[n]
    cnt = 0
    if idx == 0 or a[idx] > prev + fibs_till_n[n]: 
        return f'n+{n+1}'
    while idx:
        if idx == size-1 or a[idx] > prev + fibs_till_n[size-1]: 
            ans += cnt + 1
        if idx == 0 or a[idx-1] > prev + fibs_till_n[size-1]: 
            return ans
        if a[idx] == prev + fibs_till_n[size-1]: 
            cnt += 1
        n -= 1
        prev = a[idx]                             #Decrement n
        idx -= 1
    if n:
        return "{0}+{0}".format(ans, n + 1)
    return ans

