    if k == 1:
        return (3, [1])
    else:
        f = 0
        i = k * (k + 1) // 2
        while i < 7:
            f += F(i, mod_val%2) * 2 % MOD
            i += k + 1
        return (f, F(i, mod_val%7))[0]

