from math import sqrt

def find_possible_passwords(n, m, p):

    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    def check_password(x, m, n, p):
        for i in range(max(x + 1, 1), m):
            if gcd(i, m) == 1 and (n**gcd(i, p) - 1) % p == 0:
                return i
        return None

    total_passwords = 0
    valid_passwords = []

    while total_passwords < n:
        if gcd(p, m) != 1:
            candidate = check_password(total_passwords + 1, m, n, p)
            if candidate is not None:
                valid_passwords.append(candidate)
                total_passwords += 1
        else:
            base = pow(p, n, m)
            for i in range(1, min(n, sqrt(m)) + 1):
                if pow(base, i, m) == p:
                    valid_passwords.append(0)
                    total_passwords += 1
                else:
                    target = (m - base) // i
                    if pow(base, i, m) == p:
                        if not below_limit(target, m):
                            valid_passwords.append(target)
                            total_passwords += 1
                        if not below_limit(target, m):
                            valid_passwords.append(0)
                            total_passwords += 1

    if total_passwords < n:
        return -1
    else:
        return valid_passwords

def below_limit(target, bound):
    return target < bound


